/**
 * GhostExodus's X Listening Station Enterprise v3.4.1 renderer — EMBEDDED VERBATIM.
 *
 * This is his `src/main.tsx`, not a port of it, not a re-skin of it. The original is vendored at
 * `vendor/x-listening-station-v3.4.1/src/main.tsx` and `test/xls-embed-fidelity.test.ts` diffs this
 * file against it on every run: the ONLY permitted differences are the four mechanical edits listed
 * below. Anything else is a defect.
 *
 *   1. `createRoot(...)` bootstrap removed — this mounts inside Ghost Intel 98's React tree.
 *   2. `import './styles.css'` REMOVED. His sheet styles global element selectors (`*`, `body`,
 *      `button`, `input`…), so importing it here applied it to the whole app (the v3.73.0
 *      regression). `StationShell` now injects the SAME file, scoped to his container.
 *   3. `StrictMode` / `createRoot` imports dropped with the bootstrap.
 *   4. `function App()` → `export function App()` so the module can mount it.
 *   5. one inert `void activeCase; void postsById;` line — his `App()` declares two memos it does
 *      not read, which this project's `noUnusedLocals` rejects and his did not. Referencing them
 *      changes no behaviour and was preferred to relaxing the rule for the whole renderer or
 *      carrying a second tsconfig to avoid one line.
 *
 * WHY VERBATIM. Every previous attempt re-derived his behaviour against our own model and shipped
 * something that looked like his app but did not behave like it — five consecutive releases chasing
 * display pictures, and the standing field complaint that "your AI is still trying to wrap the
 * original with its own signature and retro Windows theme/template". His renderer is triaged and
 * correct. It is not ours to improve.
 *
 * The hardening lives at the BOUNDARY, not in here: `window.xls` is served by our preload against
 * sender-validated, Tor-gated, encrypt-at-rest main-process handlers. His UI cannot tell the
 * difference; the security posture is entirely ours.
 */
import { useEffect, useMemo, useState } from 'react';
import type { FormEvent } from 'react';


export type PostKind = 'post' | 'reply' | 'repost' | 'comment';
export type RelationshipType = 'follower' | 'following';

type CaseRecord = { id: string; name: string; purpose?: string; description: string; createdAt: string; updatedAt: string };
type Profile = {
  id: string; caseId: string; username: string; displayName: string; bio?: string; avatar?: string; location?: string; website?: string;
  enabled: boolean; imageMode?: 'on' | 'off' | 'inherit'; addedAt: string; lastCheckedAt: string | null; lastError: string | null; collectedCount: number;
};
type Post = {
  id: string; caseId: string; profileId: string; username: string; displayName?: string; avatar?: string; sourceUsername: string; url: string; text: string;
  createdAt: string; collectedAt: string; firstObservedAt?: string; lastObservedAt?: string; collectionMethod?: string;
  evidenceHash?: string; availability?: string; verifiedAt?: string | null; versionHistory?: Array<{ observedAt: string; text: string; evidenceHash?: string }>;
  kind: PostKind; isReply: boolean; parentPostId: string | null;
  metrics: { replies: number; reposts: number; likes: number; views: number }; media: string[]; mediaEvidence?: Array<{ sourceUrl: string; filePath: string; contentType: string; size: number; sha256: string; collectedAt: string }>;
};
type InvestigationNote = { id: string; caseId: string; postId: string; text: string; createdAt: string; updatedAt: string };
type RelationshipRecord = {
  id: string; caseId: string; profileId: string; sourceUsername: string; relationship: RelationshipType; username: string;
  displayName: string; bio: string; url: string; avatar: string; collectedAt: string; firstObservedAt?: string; lastObservedAt?: string;
  observedCount?: number; evidenceHash?: string;
};
type Preset = { id: string; caseId: string; name: string; keywords: string[]; mode: 'any' | 'all'; caseSensitive: boolean; profileIds: string[]; enabled: boolean; updatedAt: string };
type Match = { id: string; caseId: string; presetId: string; postId: string; matchedKeywords: string[]; createdAt: string };
type EntityRecord = { id: string; caseId: string; type: string; value: string; normalizedValue: string; postIds: string[]; sourceUsernames: string[]; firstObservedAt: string; lastObservedAt: string; count: number };
type ChangeEvent = { id: string; caseId: string; profileId: string | null; sourceUsername: string | null; type: string; summary: string; details: Record<string, unknown>; observedAt: string };
type CollectionRun = {
  id: string; caseId: string; profileId: string; username: string; operation: string; startedAt: string; completedAt: string | null;
  requestedPasses: number; passesCompleted: number; observed: number; added: number; duplicates: number; stopReason: string | null;
  reachedEnd: boolean; frontierUsernames: string[]; status: string; error: string | null;
};
type NetworkEvent = { id: string; caseId: string; profileId: string; sourceUsername: string; relationship: RelationshipType; username: string; eventType: 'newly_observed' | 'not_seen_latest'; observedAt: string; confidence: string };

type Settings = {
  autoSweep: boolean; intervalMinutes: number; scrollPasses: number; scrollDelayMs: number; retentionLimit: number;
  collectReplies: boolean; collectReposts: boolean; collectComments: boolean; collectImages: boolean; commentThreadsPerSweep: number; commentScrollPasses: number;
  relationshipScrollPasses: number; networkStagnationLimit: number; networkSnapshotLimit: number;
  archiveEnabled: boolean; archiveIntervalMinutes: number; archivePostStep: number; archivePostMaxPasses: number;
  archiveFollowers: boolean; archiveFollowing: boolean; archiveRelationshipStep: number; archiveRelationshipMaxPasses: number;
};
type ArchiveProfileProgress = { postPasses: number; followerPasses: number; followingPasses: number; lastPostRunAt: string | null; lastFollowerRunAt: string | null; lastFollowingRunAt: string | null; oldestPostAt: string | null; postAddedTotal: number; followerAddedTotal: number; followingAddedTotal: number };
type ArchiveState = { lastCycleAt: string | null; nextOperationIndex: number; cyclesCompleted: number; profiles: Record<string, ArchiveProfileProgress> };
type StationState = {
  schemaVersion: number; cases: CaseRecord[]; activeCaseId: string; profiles: Profile[]; posts: Post[]; relationships: RelationshipRecord[];
  notes: InvestigationNote[]; presets: Preset[]; matches: Match[]; entities: EntityRecord[]; profileSnapshots: unknown[];
  changeEvents: ChangeEvent[]; collectionRuns: CollectionRun[]; networkSnapshots: unknown[]; networkEvents: NetworkEvent[];
  settings: Settings; archive: ArchiveState; lastSweepAt: string | null; tor?: { enabled: boolean; connected: boolean; port: number | null; exitIp: string | null; lastCheckedAt?: string | null; error?: string | null; source?: 'integrated' | 'external' | null; bootstrapPercent?: number; bundledAvailable?: boolean };
};
type ExportFilters = { profileId?: string; kind?: 'all' | PostKind; query?: string; presetId?: string };
type NetworkFilters = { profileId?: string; relationship?: 'all' | RelationshipType; query?: string };
type SweepProgress = { message: string; current: number; total: number; running: boolean };
type NetworkIdentity = {
  username: string; displayName: string; bio: string; avatar: string; url: string; profileIds: string[];
  followerOfProfileIds: string[]; followingFromProfileIds: string[]; followerOf: string[]; followingFrom: string[];
  connectedTargets: number; overlapScore: number; firstObservedAt: string | null; lastObservedAt: string | null;
};
type NetworkPair = { profileAId: string; profileA: string; profileBId: string; profileB: string; commonFollowers: string[]; commonFollowing: string[]; commonAny: string[]; commonFollowerCount: number; commonFollowingCount: number; commonAnyCount: number };
type NetworkAnalysis = { generatedAt: string; targetCount: number; relationshipCount: number; uniqueIdentityCount: number; commonIdentityCount: number; highOverlapCount: number; pairs: NetworkPair[]; identities: NetworkIdentity[]; graph: { nodes: Array<{ id: string; type: string; label: string; username?: string; profileId?: string; score?: number; connectedTargets?: number; avatar?: string }>; edges: Array<{ id: string; source: string; target: string; relationship: RelationshipType }> } };
type HealthRow = { profileId: string; username: string; status: string; lastError: string | null; postCount: number; followerCount: number; followingCount: number; oldestPostAt: string | null; lastPostRun: CollectionRun | null; lastFollowerRun: CollectionRun | null; lastFollowingRun: CollectionRun | null; lastRun: CollectionRun | null };

type Tab = 'dashboard' | 'live' | 'sources' | 'network' | 'entities' | 'changes' | 'search' | 'notes' | 'exports' | 'cases' | 'system';

const defaultSettings: Settings = {
  autoSweep: false, intervalMinutes: 30, scrollPasses: 5, scrollDelayMs: 1100, retentionLimit: 50000,
  collectReplies: true, collectReposts: false, collectComments: false, collectImages: true, commentThreadsPerSweep: 3, commentScrollPasses: 2,
  relationshipScrollPasses: 8, networkStagnationLimit: 7, networkSnapshotLimit: 20,
  archiveEnabled: false, archiveIntervalMinutes: 240, archivePostStep: 2, archivePostMaxPasses: 40,
  archiveFollowers: false, archiveFollowing: false, archiveRelationshipStep: 3, archiveRelationshipMaxPasses: 160,
};
const emptyState: StationState = {
  schemaVersion: 8, cases: [{ id: 'case-default', name: 'Primary Campaign', purpose: 'General intelligence monitoring', description: '', createdAt: '', updatedAt: '' }], activeCaseId: 'case-default',
  profiles: [], posts: [], relationships: [], notes: [], presets: [], matches: [], entities: [], profileSnapshots: [], changeEvents: [], collectionRuns: [], networkSnapshots: [], networkEvents: [],
  settings: defaultSettings, archive: { lastCycleAt: null, nextOperationIndex: 0, cyclesCompleted: 0, profiles: {} }, lastSweepAt: null,
};
const emptyAnalysis: NetworkAnalysis = { generatedAt: '', targetCount: 0, relationshipCount: 0, uniqueIdentityCount: 0, commonIdentityCount: 0, highOverlapCount: 0, pairs: [], identities: [], graph: { nodes: [], edges: [] } };
const kindLabels: Record<PostKind, string> = { post: 'POST', reply: 'REPLY', repost: 'REPOST / RETWEET', comment: '3RD-PARTY COMMENT' };
const formatDate = (value: string | null | undefined) => { if (!value) return 'Never'; const d = new Date(value); return Number.isNaN(d.getTime()) ? value : d.toLocaleString(); };
const formatMetric = (value: number) => new Intl.NumberFormat(undefined, { notation: 'compact' }).format(value || 0);
const normalizedKind = (post: Post): PostKind => post.kind || (post.isReply ? 'reply' : 'post');
const shortHash = (value?: string) => value ? `${value.slice(0, 12)}…${value.slice(-8)}` : '—';
const escapeRegex = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function HighlightText({ text, terms }: { text: string; terms: string[] }) {
  const clean = [...new Set(terms.map((term) => term.trim()).filter(Boolean))].sort((a, b) => b.length - a.length);
  if (!clean.length) return <>{text}</>;
  const re = new RegExp(`(${clean.map(escapeRegex).join('|')})`, 'gi');
  return <>{text.split(re).map((part, index) => clean.some((term) => term.toLowerCase() === part.toLowerCase()) ? <mark className="preset-highlight" key={`${part}-${index}`}>{part}</mark> : <span key={`${part}-${index}`}>{part}</span>)}</>;
}

const avatarPromiseCache = new Map<string, Promise<string | null>>();
const NEON_GRAPH_COLORS = ['#ff1744', '#39ff14', '#ff2bd6', '#ff7a00', '#fff200', '#00b7ff', '#9d00ff', '#00ffd5'];

function avatarCacheKey(username: string, preferredUrl?: string) {
  return `${username.replace(/^@/, '').toLowerCase()}|${preferredUrl || ''}`;
}

function loadAvatar(username: string, preferredUrl?: string) {
  const key = avatarCacheKey(username, preferredUrl);
  let pending = avatarPromiseCache.get(key);
  if (!pending) {
    pending = window.xls.getAvatarDataUrl(username, preferredUrl).catch(() => null);
    avatarPromiseCache.set(key, pending);
  }
  return pending;
}

function useAvatar(username: string, preferredUrl?: string) {
  const [src, setSrc] = useState<string | null>(null);
  useEffect(() => {
    let active = true;
    if (!username) { setSrc(null); return () => { active = false; }; }
    void loadAvatar(username, preferredUrl).then((value) => { if (active) setSrc(value); });
    return () => { active = false; };
  }, [username, preferredUrl]);
  return src;
}

function IdentityAvatar({ username, preferredUrl, size = 'md', title }: { username: string; preferredUrl?: string; size?: 'xs' | 'sm' | 'md' | 'lg'; title?: string }) {
  const src = useAvatar(username, preferredUrl);
  const initial = username.replace(/^@/, '').slice(0, 1).toUpperCase() || '@';
  return <span className={`identity-avatar size-${size}`} title={title || `@${username.replace(/^@/, '')}`}>{src ? <img src={src} alt="" /> : <span>{initial}</span>}</span>;
}

function SvgIdentityAvatar({ username, preferredUrl, x, y, radius, color }: { username: string; preferredUrl?: string; x: number; y: number; radius: number; color: string }) {
  const src = useAvatar(username, preferredUrl);
  const clipId = `avatar-clip-${username.replace(/[^A-Za-z0-9_-]/g, '_')}-${Math.round(x)}-${Math.round(y)}`;
  return <g className="svg-avatar">
    <defs><clipPath id={clipId}><circle cx={x} cy={y} r={Math.max(2, radius - 2)} /></clipPath></defs>
    <circle cx={x} cy={y} r={radius} fill="#061015" stroke={color} strokeWidth="2.5" filter="url(#nodeGlow)" />
    {src ? <image href={src} x={x - radius + 2} y={y - radius + 2} width={(radius - 2) * 2} height={(radius - 2) * 2} preserveAspectRatio="xMidYMid slice" clipPath={`url(#${clipId})`} /> : <text x={x} y={y + 3} textAnchor="middle" className="avatar-initial" fill={color}>{username.replace(/^@/, '').slice(0, 1).toUpperCase() || '@'}</text>}
  </g>;
}

function MediaThumb({ postId, index }: { postId: string; index: number }) {
  const [src, setSrc] = useState<string | null>(null);
  useEffect(() => { let active = true; window.xls.getPostMediaDataUrl(postId, index).then((value) => { if (active) setSrc(value); }).catch(() => undefined); return () => { active = false; }; }, [postId, index]);
  return src ? <img src={src} alt="Archived X media" /> : <div className="media-unavailable">MEDIA NOT RETRIEVED</div>;
}

function PostCard({ post, notes, onAddNote, onUpdateNote, onDeleteNote, onOpenThread, onVerify, avatarUrl, sourceAvatarUrl, highlightTerms = [], presetNames = [] }: {
  post: Post; notes: InvestigationNote[]; onAddNote: (postId: string, text: string) => Promise<void>; onUpdateNote: (noteId: string, text: string) => Promise<void>;
  onDeleteNote: (noteId: string) => Promise<void>; onOpenThread: (postId: string) => Promise<void>; onVerify: (postId: string) => Promise<void>; avatarUrl?: string; sourceAvatarUrl?: string; highlightTerms?: string[]; presetNames?: string[];
}) {
  const kind = normalizedKind(post); const monitoredVia = post.sourceUsername && post.sourceUsername.toLowerCase() !== post.username.toLowerCase();
  const [notesOpen, setNotesOpen] = useState(false); const [draft, setDraft] = useState(''); const [editingId, setEditingId] = useState<string | null>(null); const [editingText, setEditingText] = useState(''); const [noteBusy, setNoteBusy] = useState(false);
  const add = async () => { if (!draft.trim()) return; setNoteBusy(true); try { await onAddNote(post.id, draft.trim()); setDraft(''); } finally { setNoteBusy(false); } };
  const update = async (id: string) => { if (!editingText.trim()) return; setNoteBusy(true); try { await onUpdateNote(id, editingText.trim()); setEditingId(null); setEditingText(''); } finally { setNoteBusy(false); } };
  return <article className={`post-card kind-${kind}`}>
    <div className="post-head"><div className="post-author"><IdentityAvatar username={post.username} preferredUrl={post.avatar || avatarUrl} size="sm" /><div><strong>{post.displayName || `@${post.username}`}</strong><span className="post-username">@{post.username}</span><span className={`kind ${kind}`}>{kindLabels[kind]}</span>{monitoredVia && <span className="via inline-identity"><IdentityAvatar username={post.sourceUsername} preferredUrl={sourceAvatarUrl} size="xs" />VIA @{post.sourceUsername}</span>}</div></div><time>{formatDate(post.createdAt)}</time></div>
    {presetNames.length > 0 && <div className="preset-match-row">{presetNames.map((name) => <span key={name}>MATCH: {name}</span>)}</div>}
    <p><HighlightText text={post.text} terms={highlightTerms} /></p>
    {post.media?.length > 0 && <div className="media-strip">{post.media.slice(0, 3).map((_src, index) => <MediaThumb postId={post.id} index={index} key={`${post.id}-${index}`} />)}</div>}
    <div className="metrics"><span>↩ {formatMetric(post.metrics.replies)}</span><span>⟳ {formatMetric(post.metrics.reposts)}</span><span>♥ {formatMetric(post.metrics.likes)}</span><span>◉ {formatMetric(post.metrics.views)}</span></div>
    <div className="provenance-row"><span>FIRST {formatDate(post.firstObservedAt || post.collectedAt)}</span><span>LAST {formatDate(post.lastObservedAt || post.collectedAt)}</span><span className={`availability ${post.availability || 'unknown'}`}>{(post.availability || 'UNKNOWN').toUpperCase()}</span><span title={post.evidenceHash}>SHA-256 {shortHash(post.evidenceHash)}</span></div>
    <div className="finding-actions"><div className="finding-buttons"><button className="secondary" onClick={() => void onOpenThread(post.id)}>OPEN REAL THREAD</button><button className="secondary" onClick={() => void onVerify(post.id)}>VERIFY LIVE</button><button className="text-button" onClick={() => setNotesOpen(!notesOpen)}>{notesOpen ? 'HIDE ANALYST NOTES' : `ANALYST NOTES (${notes.length})`}</button></div><span title={post.url}>{post.url}</span></div>
    {notesOpen && <div className="notes-panel"><div className="note-list">{notes.map((note) => <article className="note-entry" key={note.id}>{editingId === note.id ? <><textarea value={editingText} onChange={(e) => setEditingText(e.target.value)} /><div className="note-actions"><button disabled={noteBusy || !editingText.trim()} onClick={() => void update(note.id)}>SAVE EDIT</button><button className="secondary" onClick={() => { setEditingId(null); setEditingText(''); }}>CANCEL</button></div></> : <><p>{note.text}</p><div className="note-meta"><span>UPDATED {formatDate(note.updatedAt)}</span><div className="note-actions"><button className="text-button" onClick={() => { setEditingId(note.id); setEditingText(note.text); }}>EDIT</button><button className="text-button danger-text" onClick={() => void onDeleteNote(note.id)}>DELETE</button></div></div></>}</article>)}{notes.length === 0 && <div className="empty">No investigative notes attached.</div>}</div><div className="note-compose"><textarea value={draft} onChange={(e) => setDraft(e.target.value)} placeholder="Assessment, source caveat, verification step, or follow-up action…" /><button disabled={noteBusy || !draft.trim()} onClick={() => void add()}>ADD NOTE</button></div></div>}
  </article>;
}

function NetworkGraph({ analysis, onOpen, avatarFor }: { analysis: NetworkAnalysis; onOpen: (username: string) => void; avatarFor: (username: string) => string | undefined }) {
  const [mode, setMode] = useState<'all' | RelationshipType>('all');
  const [limit, setLimit] = useState(40);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const targets = analysis.graph.nodes.filter((n) => n.type === 'target').slice(0, 16);
  const eligibleIdentities = analysis.graph.nodes
    .filter((n) => n.type === 'identity' && Number(n.connectedTargets || 0) >= 2)
    .sort((a, b) => Number(b.connectedTargets || 0) - Number(a.connectedTargets || 0) || Number(b.score || 0) - Number(a.score || 0));
  const identities = eligibleIdentities.slice(0, Math.max(10, Math.min(100, limit)));
  const visible = new Set([...targets, ...identities].map((n) => n.id));
  const edges = analysis.graph.edges.filter((e) => visible.has(e.source) && visible.has(e.target) && (mode === 'all' || e.relationship === mode));
  const connectedNodeIds = new Set(edges.flatMap((e) => [e.source, e.target]));
  const selected = analysis.graph.nodes.find((n) => n.id === selectedId) || null;
  const selectedNeighbors = selectedId
    ? new Set(edges.filter((e) => e.source === selectedId || e.target === selectedId).flatMap((e) => [e.source, e.target]))
    : new Set<string>();

  const width = 1120;
  const height = 720;
  const center = { x: width / 2, y: height / 2 };
  const targetRadius = Math.min(175, 95 + targets.length * 8);
  const identityRadiusX = 455;
  const identityRadiusY = 290;
  const targetPos = new Map(targets.map((n, i) => {
    const angle = -Math.PI / 2 + (Math.PI * 2 * i) / Math.max(1, targets.length);
    return [n.id, { x: center.x + Math.cos(angle) * targetRadius, y: center.y + Math.sin(angle) * targetRadius }];
  }));
  const identityPos = new Map(identities.map((n, i) => {
    const angle = -Math.PI / 2 + (Math.PI * 2 * i) / Math.max(1, identities.length);
    return [n.id, { x: center.x + Math.cos(angle) * identityRadiusX, y: center.y + Math.sin(angle) * identityRadiusY }];
  }));
  const pos = (id: string) => targetPos.get(id) || identityPos.get(id);
  const dimmed = (id: string) => Boolean(selectedId && id !== selectedId && !selectedNeighbors.has(id));
  const targetColor = new Map(targets.map((node, index) => [node.id, NEON_GRAPH_COLORS[index % NEON_GRAPH_COLORS.length]]));
  const edgeColor = (edge: NetworkAnalysis['graph']['edges'][number]) => targetColor.get(edge.source) || '#00b7ff';

  return <div className="graph-shell">
    <div className="graph-toolbar">
      <div className="graph-mode">
        <button className={mode === 'all' ? 'active' : ''} onClick={() => setMode('all')}>ALL RELATIONSHIPS</button>
        <button className={mode === 'follower' ? 'active follower' : ''} onClick={() => setMode('follower')}>COMMON FOLLOWERS</button>
        <button className={mode === 'following' ? 'active following' : ''} onClick={() => setMode('following')}>COMMON FOLLOWING</button>
      </div>
      <label>VISIBLE IDENTITIES<select value={limit} onChange={(e) => setLimit(Number(e.target.value))}><option value="20">20</option><option value="40">40</option><option value="60">60</option><option value="100">100</option></select></label>
      {selectedId && <button className="secondary" onClick={() => setSelectedId(null)}>CLEAR FOCUS</button>}
    </div>
    <div className="graph-wrap mind-map-wrap">
      <svg viewBox={`0 0 ${width} ${height}`} className="network-graph mind-map" role="img" aria-label="Interactive common follower and following relationship graph">
        <defs>
          <filter id="nodeGlow" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="3" result="blur" /><feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge></filter>
        </defs>
        <circle cx={center.x} cy={center.y} r={targetRadius + 38} className="mind-ring inner" />
        <ellipse cx={center.x} cy={center.y} rx={identityRadiusX + 24} ry={identityRadiusY + 24} className="mind-ring outer" />
        {edges.map((e) => {
          const a = pos(e.source); const b = pos(e.target); if (!a || !b) return null;
          const muted = Boolean(selectedId && e.source !== selectedId && e.target !== selectedId);
          const cx = (a.x + b.x + center.x) / 3; const cy = (a.y + b.y + center.y) / 3;
          return <path key={e.id} d={`M ${a.x} ${a.y} Q ${cx} ${cy} ${b.x} ${b.y}`} className={`edge ${e.relationship} ${muted ? 'muted' : ''}`} style={{ stroke: edgeColor(e) }} />;
        })}
        <g className="mind-center"><circle cx={center.x} cy={center.y} r="42" /><text x={center.x} y={center.y - 4} textAnchor="middle">COMMON</text><text x={center.x} y={center.y + 12} textAnchor="middle">NETWORK</text></g>
        {targets.map((n, index) => { const p = targetPos.get(n.id)!; const muted = dimmed(n.id) || !connectedNodeIds.has(n.id); const color = NEON_GRAPH_COLORS[index % NEON_GRAPH_COLORS.length]; return <g key={n.id} className={`mind-node target ${muted ? 'dimmed' : ''} ${selectedId === n.id ? 'selected' : ''}`} onClick={() => setSelectedId(selectedId === n.id ? null : n.id)}><SvgIdentityAvatar username={n.username || n.label} preferredUrl={n.username ? avatarFor(n.username) : undefined} x={p.x} y={p.y} radius={18} color={color} /><text x={p.x} y={p.y + 34} textAnchor="middle" style={{ fill: color }}>{n.label}</text></g>; })}
        {identities.map((n, index) => { const p = identityPos.get(n.id)!; const muted = dimmed(n.id) || !connectedNodeIds.has(n.id); const radius = 9 + Math.min(11, Number(n.connectedTargets || 1) * 2); const color = NEON_GRAPH_COLORS[(index + targets.length) % NEON_GRAPH_COLORS.length]; return <g key={n.id} className={`mind-node identity click-node ${muted ? 'dimmed' : ''} ${selectedId === n.id ? 'selected' : ''}`} onClick={() => setSelectedId(selectedId === n.id ? null : n.id)} onDoubleClick={() => n.username && onOpen(n.username)}><SvgIdentityAvatar username={n.username || n.label} preferredUrl={n.username ? avatarFor(n.username) : undefined} x={p.x} y={p.y} radius={radius} color={color} /><circle cx={p.x + radius - 2} cy={p.y - radius + 2} r="7" className="score-badge" style={{ fill: color }} /><text className="score-label" x={p.x + radius - 2} y={p.y - radius + 5} textAnchor="middle">{n.score || 0}</text><text x={p.x} y={p.y + radius + 15} textAnchor="middle" style={{ fill: color }}>{n.label}</text></g>; })}
      </svg>
      <div className="graph-legend"><span><i className="legend-rainbow" />Neon color = target / identity cluster</span><span><i className="legend-line follower" />Solid = identity follows target</span><span><i className="legend-line following" />Dashed = target follows identity</span><span>Node size = cross-target overlap</span></div>
    </div>
    <div className="graph-inspector">
      {selected ? <><div><strong>{selected.label}</strong><span>{selected.type === 'identity' ? `${selected.connectedTargets || 0} connected targets · overlap score ${selected.score || 0}` : 'Monitored target source'}</span></div>{selected.type === 'identity' && selected.username && <button onClick={() => onOpen(selected.username!)}>OPEN X PROFILE</button>}<small>Click a node to focus its relationships. Double-click an identity to open its live X profile.</small></> : <><div><strong>RELATIONSHIP MIND MAP</strong><span>{identities.length} common identities · {edges.length} visible relationships</span></div><small>Select a node to isolate its connections.</small></>}
    </div>
  </div>;
}

export function App() {
  const [state, setState] = useState<StationState>(emptyState); const [tab, setTab] = useState<Tab>('dashboard'); const [sessionConnected, setSessionConnected] = useState(false); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState('Enterprise station ready.'); const [progress, setProgress] = useState<SweepProgress>({ message: 'Idle', current: 0, total: 0, running: false });
  const [analysis, setAnalysis] = useState<NetworkAnalysis>(emptyAnalysis); const [health, setHealth] = useState<HealthRow[]>([]);
  const [newUsername, setNewUsername] = useState(''); const [feedProfile, setFeedProfile] = useState('all'); const [feedKinds, setFeedKinds] = useState<Record<PostKind, boolean>>({ post: true, reply: true, repost: true, comment: true });
  const [searchQuery, setSearchQuery] = useState(''); const [searchProfile, setSearchProfile] = useState('all'); const [searchKind, setSearchKind] = useState<'all' | PostKind>('all'); const [exportFilters, setExportFilters] = useState<ExportFilters>({ kind: 'all' });
  const [presetName, setPresetName] = useState(''); const [presetKeywords, setPresetKeywords] = useState(''); const [presetMode, setPresetMode] = useState<'any' | 'all'>('any'); const [presetCase, setPresetCase] = useState(false); const [presetProfiles, setPresetProfiles] = useState<string[]>([]);
  const [settingsDraft, setSettingsDraft] = useState<Settings>(defaultSettings); const [networkProfile, setNetworkProfile] = useState(''); const [networkRelationship, setNetworkRelationship] = useState<'all' | RelationshipType>('all'); const [networkQuery, setNetworkQuery] = useState(''); const [networkMinTargets, setNetworkMinTargets] = useState(2);
  const [noteProfile, setNoteProfile] = useState('all'); const [noteQuery, setNoteQuery] = useState(''); const [entityQuery, setEntityQuery] = useState(''); const [entityType, setEntityType] = useState('all');
  const [caseName, setCaseName] = useState(''); const [casePurpose, setCasePurpose] = useState(''); const [caseDescription, setCaseDescription] = useState('');
  const [campaignEditorOpen, setCampaignEditorOpen] = useState(false); const [campaignEditorId, setCampaignEditorId] = useState<string | null>(null);
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null); const [presetMatchesOnly, setPresetMatchesOnly] = useState(false);
  const [torBusy, setTorBusy] = useState(false);

  const refreshInsights = async () => { try { const [network, rows] = await Promise.all([window.xls.getNetworkAnalysis(), window.xls.getCollectionHealth()]); setAnalysis(network); setHealth(rows); } catch { /* app may be closing */ } };
  useEffect(() => {
    let active = true;
    window.xls.getState().then((next) => { if (!active) return; setState(next); setSettingsDraft({ ...defaultSettings, ...next.settings }); if (next.profiles[0]) setNetworkProfile(next.profiles[0].id); void refreshInsights(); }).catch((e) => setNotice(String(e)));
    window.xls.getSessionStatus().then((r) => active && setSessionConnected(r.connected)).catch(() => undefined);
    const torTimer = window.setInterval(() => { void window.xls.getTorStatus().catch(() => undefined); }, 30000);
    const offState = window.xls.onStateChanged((next) => { setState(next); setSettingsDraft({ ...defaultSettings, ...next.settings }); setNetworkProfile((current) => current && next.profiles.some((p: Profile) => p.id === current) ? current : (next.profiles[0]?.id || '')); void refreshInsights(); });
    const offProgress = window.xls.onSweepProgress(setProgress);
    const offBackgroundError = window.xls.onBackgroundError((payload) => { setNotice(`BACKGROUND ${payload.context.toUpperCase()}: ${payload.message}`); });
    const onRendererError = (event: ErrorEvent) => { setNotice(`RENDERER ERROR: ${event.message || 'Unknown JavaScript error'}`); };
    const onRendererRejection = (event: PromiseRejectionEvent) => { const reason = event.reason instanceof Error ? event.reason.message : String(event.reason || 'Unknown rejected promise'); setNotice(`RENDERER ASYNC ERROR: ${reason}`); };
    window.addEventListener('error', onRendererError);
    window.addEventListener('unhandledrejection', onRendererRejection);
    return () => { active = false; window.clearInterval(torTimer); offState(); offProgress(); offBackgroundError(); window.removeEventListener('error', onRendererError); window.removeEventListener('unhandledrejection', onRendererRejection); };
  }, []);

  const activeCampaign = state.cases.find((c) => c.id === state.activeCaseId) || state.cases[0];
  const activeCase = activeCampaign;
  const avatarLookup = useMemo(() => {
    const map = new Map<string, string>();
    const put = (username?: string, avatar?: string) => { const key = String(username || '').replace(/^@/, '').toLowerCase(); if (key && avatar && !map.has(key)) map.set(key, avatar); };
    for (const profile of state.profiles) put(profile.username, profile.avatar);
    for (const row of state.relationships) put(row.username, row.avatar);
    for (const post of state.posts) put(post.username, post.avatar);
    return map;
  }, [state.profiles, state.relationships, state.posts]);
  const avatarFor = (username: string) => avatarLookup.get(String(username || '').replace(/^@/, '').toLowerCase());
  const postsById = useMemo(() => new Map(state.posts.map((p) => [p.id, p])), [state.posts]);
  void activeCase; void postsById; // (embed edit 5) see header
  const notesByPost = useMemo(() => { const m = new Map<string, InvestigationNote[]>(); for (const n of state.notes) { const a = m.get(n.postId) || []; a.push(n); m.set(n.postId, a); } for (const a of m.values()) a.sort((x, y) => y.updatedAt.localeCompare(x.updatedAt)); return m; }, [state.notes]);
  const presetById = useMemo(() => new Map(state.presets.map((preset) => [preset.id, preset])), [state.presets]);
  const presetMatchByPost = useMemo(() => { const map = new Map<string, { terms: string[]; names: string[] }>(); for (const match of state.matches) { const preset = presetById.get(match.presetId); if (!preset || preset.enabled === false) continue; const row = map.get(match.postId) || { terms: [], names: [] }; row.terms.push(...match.matchedKeywords); row.names.push(preset.name); map.set(match.postId, row); } return map; }, [state.matches, presetById]);
  const postKindCounts = useMemo(() => { const c: Record<PostKind, number> = { post: 0, reply: 0, repost: 0, comment: 0 }; for (const p of state.posts) c[normalizedKind(p)]++; return c; }, [state.posts]);
  const feedPosts = useMemo(() => state.posts.filter((p) => feedProfile === 'all' || p.profileId === feedProfile).filter((p) => feedKinds[normalizedKind(p)]).slice(0, 1500), [state.posts, feedProfile, feedKinds]);
  const searchResults = useMemo(() => { const q = searchQuery.trim().toLowerCase(); return state.posts.filter((p) => { if (searchProfile !== 'all' && p.profileId !== searchProfile) return false; if (searchKind !== 'all' && normalizedKind(p) !== searchKind) return false; if (presetMatchesOnly && !presetMatchByPost.has(p.id)) return false; const notes = (notesByPost.get(p.id) || []).map((n) => n.text).join(' ').toLowerCase(); return !q || p.text.toLowerCase().includes(q) || p.username.toLowerCase().includes(q) || notes.includes(q); }).slice(0, 1500); }, [state.posts, searchQuery, searchProfile, searchKind, notesByPost, presetMatchesOnly, presetMatchByPost]);
  const selectedNetworkProfile = state.profiles.find((p) => p.id === networkProfile); const followerCount = state.relationships.filter((r) => r.profileId === networkProfile && r.relationship === 'follower').length; const followingCount = state.relationships.filter((r) => r.profileId === networkProfile && r.relationship === 'following').length;
  const networkRows = useMemo(() => { const q = networkQuery.trim().toLowerCase(); return state.relationships.filter((r) => (!networkProfile || r.profileId === networkProfile) && (networkRelationship === 'all' || r.relationship === networkRelationship) && (!q || [r.username, r.displayName, r.bio].some((v) => String(v).toLowerCase().includes(q)))).slice(0, 3000); }, [state.relationships, networkProfile, networkRelationship, networkQuery]);
  const overlapIdentities = useMemo(() => analysis.identities.filter((i) => i.connectedTargets >= Math.max(2, networkMinTargets)).slice(0, 500), [analysis, networkMinTargets]);
  const entities = useMemo(() => { const q = entityQuery.toLowerCase().trim(); return state.entities.filter((e) => (entityType === 'all' || e.type === entityType) && (!q || e.value.toLowerCase().includes(q) || e.sourceUsernames.some((u) => u.toLowerCase().includes(q)))).sort((a, b) => b.count - a.count).slice(0, 2000); }, [state.entities, entityQuery, entityType]);
  const entityTypes = useMemo(() => [...new Set(state.entities.map((e) => e.type))].sort(), [state.entities]);
  const notedPosts = useMemo(() => { const q = noteQuery.toLowerCase().trim(); return state.posts.filter((p) => { const n = notesByPost.get(p.id) || []; if (!n.length) return false; if (noteProfile !== 'all' && p.profileId !== noteProfile) return false; return !q || p.text.toLowerCase().includes(q) || p.username.toLowerCase().includes(q) || n.some((x) => x.text.toLowerCase().includes(q)); }); }, [state.posts, noteProfile, noteQuery, notesByPost]);
  const recentRuns = [...state.collectionRuns].sort((a, b) => String(b.startedAt).localeCompare(String(a.startedAt))).slice(0, 100); const recentChanges = [...state.changeEvents].sort((a, b) => b.observedAt.localeCompare(a.observedAt)).slice(0, 500); const recentNetworkEvents = [...state.networkEvents].sort((a, b) => b.observedAt.localeCompare(a.observedAt)).slice(0, 100);
  const archiveRows = state.profiles.map((profile) => ({ profile, progress: state.archive?.profiles?.[profile.id] })); const oldestArchivedPost = state.posts.map((p) => p.createdAt).filter(Boolean).sort()[0] || null; const archiveOperationCount = state.profiles.filter((p) => p.enabled !== false).length * (1 + (state.settings.archiveFollowers ? 1 : 0) + (state.settings.archiveFollowing ? 1 : 0));

  const run = async (job: () => Promise<unknown>, success: string) => { setBusy(true); try { await job(); setNotice(success); await refreshInsights(); } catch (e) { setNotice(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); try { setSessionConnected((await window.xls.getSessionStatus()).connected); } catch { /* closing */ } } };
  const renderPost = (post: Post, highlight = false) => { const presetMatch = highlight ? presetMatchByPost.get(post.id) : undefined; return <PostCard key={post.id} post={post} avatarUrl={avatarFor(post.username)} sourceAvatarUrl={avatarFor(post.sourceUsername)} notes={notesByPost.get(post.id) || []} highlightTerms={presetMatch?.terms || []} presetNames={presetMatch?.names || []} onAddNote={async (id, text) => { await window.xls.addNote(id, text); setNotice('Investigative note added.'); }} onUpdateNote={async (id, text) => { await window.xls.updateNote(id, text); setNotice('Investigative note updated.'); }} onDeleteNote={async (id) => { await window.xls.removeNote(id); setNotice('Investigative note deleted.'); }} onOpenThread={async (id) => { await window.xls.openThread(id); setNotice('Authenticated X thread opened.'); }} onVerify={async (id) => { const r = await window.xls.verifyPost(id); setNotice(`Live verification: ${r.availability}.`); }} />; };
  const openIdentity = (username: string) => void run(() => window.xls.openIdentityProfile(username), `Opened @${username}.`);
  const addProfile = (e: FormEvent) => { e.preventDefault(); if (!newUsername.trim()) return; void run(async () => { await window.xls.addProfile(newUsername.trim()); setNewUsername(''); }, 'Source added to active campaign.'); };
  const extractNetwork = (relationship: RelationshipType | 'both') => { if (!networkProfile) return; void run(async () => { if (relationship === 'both') { await window.xls.extractRelationships(networkProfile, 'follower'); await window.xls.extractRelationships(networkProfile, 'following'); } else await window.xls.extractRelationships(networkProfile, relationship); }, 'Network extraction complete.'); };
  const exportNetwork = (kind: 'json' | 'csv') => { const f: NetworkFilters = { profileId: networkProfile || undefined, relationship: networkRelationship, query: networkQuery || undefined }; void run(async () => { const r = kind === 'json' ? await window.xls.exportRelationshipsJson(f) : await window.xls.exportRelationshipsCsv(f); if (!r.canceled) setNotice(`Exported ${r.count || 0} records. SHA-256 sidecar created.`); }, `${kind.toUpperCase()} network export complete.`); };
  const exportData = (kind: 'json' | 'pdf') => void run(async () => { const r = kind === 'json' ? await window.xls.exportJson(exportFilters) : await window.xls.exportPdf(exportFilters); if (!r.canceled) setNotice(`Exported ${r.count || 0} records. SHA-256 sidecar created.`); }, `${kind.toUpperCase()} export complete.`);
  const runArchiveStep = () => void run(async () => { const r = await window.xls.runArchiveStep(); setNotice(`Archive @${r.username}: ${r.added} new records, depth ${r.depth}.`); }, 'Archive step complete.');
  const toggleTor = async () => { setTorBusy(true); try { const result = await window.xls.toggleTor(!state.tor?.enabled); setNotice(result.connected ? `Connected over ${result.source === 'integrated' ? 'integrated Tor' : 'Tor'}${result.exitIp ? ` · exit ${result.exitIp}` : ''}.` : (result.enabled ? `Tor could not connect: ${result.error || 'Integrated Tor did not finish connecting.'}` : 'Tor disconnected.')); } catch (e) { setNotice(e instanceof Error ? e.message : String(e)); } finally { setTorBusy(false); } };
  const toggleCampaignImages = () => void run(() => window.xls.setCampaignImages(!state.settings.collectImages), `Campaign image retrieval ${state.settings.collectImages ? 'disabled' : 'enabled'}.`);
  const startNewCampaign = () => { setCampaignEditorId(null); setCaseName(''); setCasePurpose(''); setCaseDescription(''); setCampaignEditorOpen(true); };
  const editCampaign = (campaign = activeCampaign) => { if (!campaign) return; setCampaignEditorId(campaign.id); setCaseName(campaign.name); setCasePurpose(campaign.purpose || ''); setCaseDescription(campaign.description || ''); setCampaignEditorOpen(true); };
  const saveCampaign = () => void run(async () => { if (!caseName.trim()) throw new Error('Campaign name is required.'); if (campaignEditorId) await window.xls.updateCampaign(campaignEditorId, { name: caseName.trim(), purpose: casePurpose.trim(), description: caseDescription.trim() }); else await window.xls.createCampaign({ name: caseName.trim(), purpose: casePurpose.trim(), description: caseDescription.trim() }); setCampaignEditorOpen(false); }, campaignEditorId ? 'Campaign updated.' : 'Campaign created and activated.');
  const deleteCampaign = (campaign = activeCampaign) => { if (!campaign || state.cases.length <= 1) return; if (!window.confirm(`Delete campaign "${campaign.name}" and all locally stored data assigned to it? This cannot be undone.`)) return; void run(() => window.xls.deleteCampaign(campaign.id), 'Campaign deleted.'); };
  const editPreset = (preset: Preset) => { setEditingPresetId(preset.id); setPresetName(preset.name); setPresetKeywords(preset.keywords.join('\n')); setPresetMode(preset.mode); setPresetCase(preset.caseSensitive); setPresetProfiles(preset.profileIds || []); };
  const clearPresetEditor = () => { setEditingPresetId(null); setPresetName(''); setPresetKeywords(''); setPresetMode('any'); setPresetCase(false); setPresetProfiles([]); };

  const nav: Array<{ id: Tab; label: string; badge?: number }> = [
    { id: 'dashboard', label: 'COMMAND BOARD' }, { id: 'live', label: 'LIVE FEED', badge: state.posts.length }, { id: 'sources', label: 'TARGET SOURCES', badge: state.profiles.length },
    { id: 'network', label: 'FOLLOWER NETWORK', badge: analysis.commonIdentityCount }, { id: 'entities', label: 'ENTITY INDEX', badge: state.entities.length }, { id: 'changes', label: 'CHANGE INTEL', badge: state.changeEvents.length + state.networkEvents.length },
    { id: 'search', label: 'SEARCH', badge: state.presets.length }, { id: 'notes', label: 'ANALYST NOTES', badge: state.notes.length }, { id: 'exports', label: 'EXPORTS' }, { id: 'cases', label: 'CAMPAIGNS', badge: state.cases.length }, { id: 'system', label: 'SYSTEM' },
  ];

  return <div className="app-shell">
    <aside><div className="brand"><div className="seal">CD</div><div><strong>CYBERVS DOMINATVS</strong><span>X LISTENING STATION</span><small>ENTERPRISE // by GhostExodus</small></div></div><div className="campaign-dock"><span>ACTIVE CAMPAIGN</span><select value={state.activeCaseId} onChange={(e) => void run(() => window.xls.switchCampaign(e.target.value), 'Campaign switched.')}>{state.cases.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select><small>{activeCampaign?.purpose || 'No purpose defined.'}</small><div><button onClick={startNewCampaign}>+ NEW</button><button className="secondary" onClick={() => editCampaign()}>EDIT</button><button className="secondary" onClick={() => setTab('cases')}>MANAGE</button></div></div><nav>{nav.map((n) => <button key={n.id} className={tab === n.id ? 'active' : ''} onClick={() => setTab(n.id)}><span>{n.label}</span>{n.badge !== undefined && <b>{n.badge}</b>}</button>)}</nav><div className={`tor-box ${state.tor?.connected ? 'connected' : state.tor?.enabled ? 'connecting' : ''}`}><button onClick={() => void toggleTor()} disabled={torBusy}><span className="status-dot" /><div><strong>{state.tor?.connected ? 'CONNECTED OVER TOR' : state.tor?.enabled ? 'CONNECTING OVER TOR' : 'TOR DISCONNECTED'}</strong><small>{state.tor?.connected ? `${state.tor.source === 'integrated' ? 'INTEGRATED TOR' : 'EXTERNAL TOR'} · SOCKS ${state.tor.port}${state.tor.exitIp ? ` · ${state.tor.exitIp}` : ''}` : (state.tor?.enabled ? `${state.tor?.bundledAvailable === false ? 'Integrated runtime unavailable' : `Integrated Tor bootstrapping${state.tor?.bootstrapPercent ? ` · ${state.tor.bootstrapPercent}%` : ''}`}` : 'Integrated Tor ready on demand')}</small><span className="tor-action">{torBusy ? 'STARTING TOR…' : state.tor?.enabled ? 'DISCONNECT OVER TOR' : 'CONNECT OVER TOR'}</span></div></button></div><div className="session-box"><span className={`status-dot ${sessionConnected ? 'online' : ''}`} /><div><strong>{sessionConnected ? 'X SESSION ONLINE' : 'X SESSION OFFLINE'}</strong><small>{progress.running ? progress.message : `CAMPAIGN: ${activeCampaign?.name || '—'}`}</small></div></div></aside>
    <main><section className="brand-masthead"><img src="./cybervs-dominatvs-banner.webp" alt="CYBERVS DOMINATVS" /><div className="brand-masthead-caption"><span>X LISTENING STATION // ENTERPRISE</span><strong>by GhostExodus</strong></div></section>
      <header className="topbar"><div><span className="eyebrow">CYBERVS DOMINATVS X LISTENING STATION // ENTERPRISE v3.4.1</span><h1>{nav.find((n) => n.id === tab)?.label}</h1><small className="case-context">ACTIVE CAMPAIGN: {activeCampaign?.name || 'Unknown'} · {activeCampaign?.purpose || 'No purpose defined'}</small></div><div className="actions"><button className={`image-toggle ${state.settings.collectImages ? 'on' : 'off'}`} onClick={toggleCampaignImages}>IMAGES: {state.settings.collectImages ? 'ON' : 'OFF'}</button><button className="secondary" onClick={() => setTab('system')}>{sessionConnected ? 'SESSION CONNECTED' : 'CONNECT X'}</button><button disabled={busy || progress.running || !state.profiles.length} onClick={() => void run(window.xls.refreshAll, 'Collection sweep complete.')}>RUN SWEEP</button></div></header>
      <div className="notice">{progress.running ? progress.message : notice}</div>

      {tab === 'dashboard' && <section className="page-grid">
        <article className="stat"><span>MONITORED SOURCES</span><strong>{state.profiles.length}</strong><small>active campaign</small></article><article className="stat"><span>LOCAL FINDINGS</span><strong>{state.posts.length}</strong><small>{postKindCounts.reply} replies · {postKindCounts.comment} comments</small></article><article className="stat"><span>UNIQUE NETWORK IDENTITIES</span><strong>{analysis.uniqueIdentityCount}</strong><small>{analysis.commonIdentityCount} common across targets</small></article><article className="stat"><span>HIGH-OVERLAP IDENTITIES</span><strong>{analysis.highOverlapCount}</strong><small>connected to ≥ half of targets</small></article><article className="stat"><span>EXTRACTED ENTITIES</span><strong>{state.entities.length}</strong><small>mentions, domains, URLs, contacts, crypto</small></article>
        <article className="panel wide"><div className="panel-title"><h2>COLLECTION HEALTH</h2><b>{health.filter((h) => h.status === 'HEALTHY').length}/{health.length} HEALTHY</b></div><div className="health-grid">{health.map((h) => <div className={`health-card status-${h.status.toLowerCase()}`} key={h.profileId}><div className="health-identity"><IdentityAvatar username={h.username} preferredUrl={avatarFor(h.username)} size="sm" /><strong>@{h.username}</strong><b>{h.status}</b></div><div className="health-metrics"><span>POSTS {h.postCount}</span><span>FOLLOWERS {h.followerCount}</span><span>FOLLOWING {h.followingCount}</span></div><small>oldest post {formatDate(h.oldestPostAt)}</small><small>last run {formatDate(h.lastRun?.completedAt || h.lastRun?.startedAt)}</small>{h.lastRun && <small>{h.lastRun.observed} observed · {h.lastRun.added} new · {h.lastRun.duplicates} duplicate · stop {h.lastRun.stopReason || '—'}</small>}{h.lastError && <small className="bad">{h.lastError}</small>}</div>)}{!health.length && <div className="empty">No sources configured.</div>}</div></article>
        <article className="panel wide"><div className="panel-title"><h2>NETWORK INTELLIGENCE</h2><b>AUTOMATIC CROSS-CHECK</b></div><div className="pair-grid">{analysis.pairs.slice(0, 6).map((p) => <article className="pair-card" key={`${p.profileAId}:${p.profileBId}`}><strong className="pair-identities"><span><IdentityAvatar username={p.profileA} preferredUrl={avatarFor(p.profileA)} size="xs" />@{p.profileA}</span><span>↔</span><span><IdentityAvatar username={p.profileB} preferredUrl={avatarFor(p.profileB)} size="xs" />@{p.profileB}</span></strong><span>{p.commonFollowerCount} common followers</span><span>{p.commonFollowingCount} common following</span><span>{p.commonAnyCount} common identities overall</span></article>)}{analysis.pairs.length === 0 && <div className="empty">Add at least two sources and extract networks to calculate overlap.</div>}</div></article>
        <article className="panel wide"><div className="panel-title"><h2>RECENT COLLECTION</h2><b>{state.posts.length} LOCAL</b></div><div className="post-list compact">{state.posts.slice(0, 8).map((post) => renderPost(post))}{!state.posts.length && <div className="empty">No records collected.</div>}</div></article>
      </section>}

      {tab === 'live' && <section className="single-page"><div className="panel toolbar live-toolbar"><label>SOURCE<select value={feedProfile} onChange={(e) => setFeedProfile(e.target.value)}><option value="all">ALL SOURCES</option>{state.profiles.map((p) => <option key={p.id} value={p.id}>@{p.username}</option>)}</select></label><div className="kind-checks">{(Object.keys(kindLabels) as PostKind[]).map((k) => <label className="check" key={k}><input type="checkbox" checked={feedKinds[k]} onChange={(e) => setFeedKinds({ ...feedKinds, [k]: e.target.checked })} />{kindLabels[k]} ({postKindCounts[k]})</label>)}</div><span>{feedPosts.length} displayed</span></div><div className="post-list">{feedPosts.map((post) => renderPost(post))}{!feedPosts.length && <div className="empty-large">No records match these feed filters.</div>}</div></section>}

      {tab === 'sources' && <section className="single-page"><form className="panel add-source" onSubmit={addProfile}><label>ADD X PROFILE<input value={newUsername} onChange={(e) => setNewUsername(e.target.value)} placeholder="username or https://x.com/username" /></label><button>ADD SOURCE</button></form><div className="source-cards">{state.profiles.map((p) => <article className="source-card" key={p.id}><div><IdentityAvatar username={p.username} preferredUrl={p.avatar} size="lg" /><div><h3>@{p.username}</h3><p>{p.displayName} · {p.collectedCount} findings</p>{p.bio && <small>{p.bio}</small>}</div></div>{p.lastError && <div className="error-line">{p.lastError}</div>}<div className="card-actions"><button className={`image-toggle ${(p.imageMode === 'inherit' ? state.settings.collectImages : p.imageMode === 'on') ? 'on' : 'off'}`} onClick={() => { const effective = p.imageMode === 'inherit' ? state.settings.collectImages : p.imageMode === 'on'; void run(() => window.xls.setProfileImageMode(p.id, effective ? 'off' : 'on'), `Image retrieval ${effective ? 'disabled' : 'enabled'} for @${p.username}.`); }}>IMAGES {(p.imageMode === 'inherit' ? state.settings.collectImages : p.imageMode === 'on') ? 'ON' : 'OFF'}</button><button onClick={() => void run(() => window.xls.refreshProfile(p.id), `Collection complete for @${p.username}.`)}>REFRESH</button><button className="secondary" onClick={() => void run(() => window.xls.openProfileFeed(p.id), 'Native X feed opened.')}>VIEW X</button><button className="secondary" onClick={() => { setNetworkProfile(p.id); setTab('network'); }}>NETWORK</button><button className="danger" onClick={() => void run(() => window.xls.removeProfile(p.id), `Removed @${p.username}.`)}>REMOVE</button></div></article>)}{!state.profiles.length && <div className="empty-large">No source profiles in this campaign.</div>}</div></section>}

      {tab === 'network' && <section className="single-page network-page"><div className="panel network-controls"><label>TARGET SOURCE<select value={networkProfile} onChange={(e) => setNetworkProfile(e.target.value)}><option value="">ALL / SELECT</option>{state.profiles.map((p) => <option key={p.id} value={p.id}>@{p.username}</option>)}</select></label><label>VIEW<select value={networkRelationship} onChange={(e) => setNetworkRelationship(e.target.value as 'all' | RelationshipType)}><option value="all">FOLLOWERS + FOLLOWING</option><option value="follower">FOLLOWERS</option><option value="following">FOLLOWING</option></select></label><label>SEARCH<input value={networkQuery} onChange={(e) => setNetworkQuery(e.target.value)} placeholder="name, username, bio" /></label><div className="card-actions"><button disabled={!networkProfile || progress.running} onClick={() => extractNetwork('follower')}>EXTRACT FOLLOWERS</button><button disabled={!networkProfile || progress.running} onClick={() => extractNetwork('following')}>EXTRACT FOLLOWING</button><button className="secondary" disabled={!networkProfile || progress.running} onClick={() => extractNetwork('both')}>EXTRACT BOTH</button></div></div>
        <div className="network-stats"><article className="stat"><span>SELECTED FOLLOWERS</span><strong>{followerCount}</strong>{selectedNetworkProfile ? <small className="inline-identity"><IdentityAvatar username={selectedNetworkProfile.username} preferredUrl={selectedNetworkProfile.avatar || avatarFor(selectedNetworkProfile.username)} size="xs" />@{selectedNetworkProfile.username}</small> : <small>all targets</small>}</article><article className="stat"><span>SELECTED FOLLOWING</span><strong>{followingCount}</strong><small>locally observed</small></article><article className="stat"><span>COMMON IDENTITIES</span><strong>{analysis.commonIdentityCount}</strong><small>connected to ≥2 targets</small></article><article className="stat"><span>HIGH OVERLAP</span><strong>{analysis.highOverlapCount}</strong><small>priority review candidates</small></article></div>
        <article className="panel"><div className="panel-title"><h2>COMMON FOLLOWERS / FOLLOWING</h2><b>AUTOMATIC</b></div><div className="pair-grid">{analysis.pairs.map((p) => <details className="pair-card" key={`${p.profileAId}:${p.profileBId}`}><summary><strong className="pair-identities"><span><IdentityAvatar username={p.profileA} preferredUrl={avatarFor(p.profileA)} size="xs" />@{p.profileA}</span><span>↔</span><span><IdentityAvatar username={p.profileB} preferredUrl={avatarFor(p.profileB)} size="xs" />@{p.profileB}</span></strong><span>{p.commonFollowerCount} followers · {p.commonFollowingCount} following · {p.commonAnyCount} total</span></summary><div className="common-groups"><div><h4>COMMON FOLLOWERS</h4><div className="identity-chips">{p.commonFollowers.slice(0, 100).map((u) => <button key={u} className="identity-chip" onClick={() => openIdentity(u)}><IdentityAvatar username={u} preferredUrl={avatarFor(u)} size="xs" />@{u}</button>)}{!p.commonFollowers.length && <span>None observed.</span>}</div></div><div><h4>COMMON FOLLOWING</h4><div className="identity-chips">{p.commonFollowing.slice(0, 100).map((u) => <button key={u} className="identity-chip" onClick={() => openIdentity(u)}><IdentityAvatar username={u} preferredUrl={avatarFor(u)} size="xs" />@{u}</button>)}{!p.commonFollowing.length && <span>None observed.</span>}</div></div></div></details>)}{!analysis.pairs.length && <div className="empty">At least two extracted target networks are required.</div>}</div></article>
        <article className="panel"><div className="panel-title"><h2>MULTI-TARGET OVERLAP</h2><b>{overlapIdentities.length}</b></div><label>MINIMUM CONNECTED TARGETS<input type="number" min="2" max={Math.max(2, state.profiles.length)} value={networkMinTargets} onChange={(e) => setNetworkMinTargets(Number(e.target.value))} /></label><div className="overlap-table">{overlapIdentities.map((i) => <div className="overlap-row" key={i.username}><button className="identity-main" onClick={() => openIdentity(i.username)}><IdentityAvatar username={i.username} preferredUrl={i.avatar || avatarFor(i.username)} size="sm" />@{i.username}</button><span>{i.connectedTargets}/{analysis.targetCount} targets</span><strong>{i.overlapScore}</strong><span className="overlap-connections"><em>follows:</em>{i.followerOf.length ? i.followerOf.map((x) => <span className="inline-identity" key={`follows-${i.username}-${x}`}><IdentityAvatar username={x} preferredUrl={avatarFor(x)} size="xs" />@{x}</span>) : '—'}</span><span className="overlap-connections"><em>followed by targets:</em>{i.followingFrom.length ? i.followingFrom.map((x) => <span className="inline-identity" key={`followed-${i.username}-${x}`}><IdentityAvatar username={x} preferredUrl={avatarFor(x)} size="xs" />@{x}</span>) : '—'}</span></div>)}{!overlapIdentities.length && <div className="empty">No identities meet this overlap threshold.</div>}</div></article>
        <article className="panel"><div className="panel-title"><h2>COMMON NETWORK MIND MAP</h2><b>INTERACTIVE</b></div><NetworkGraph analysis={analysis} onOpen={openIdentity} avatarFor={avatarFor} /></article>
        <article className="panel"><div className="panel-title"><h2>RECENT NETWORK DELTAS</h2><b>{recentNetworkEvents.length}</b></div><p className="caveat">“Not seen in latest scan” is a review candidate, not proof of an unfollow. X can truncate or reorder lists.</p><div className="event-list">{recentNetworkEvents.map((e) => <div key={e.id} className={`event ${e.eventType}`}><time>{formatDate(e.observedAt)}</time><button className="identity-main compact" onClick={() => openIdentity(e.username)}><IdentityAvatar username={e.username} preferredUrl={avatarFor(e.username)} size="xs" />@{e.username}</button><span>{e.eventType === 'newly_observed' ? 'NEWLY OBSERVED' : 'NOT SEEN IN LATEST COMPARABLE SCAN'}</span><small className="inline-identity"><IdentityAvatar username={e.sourceUsername} preferredUrl={avatarFor(e.sourceUsername)} size="xs" />{e.relationship.toUpperCase()} of @{e.sourceUsername}</small></div>)}{!recentNetworkEvents.length && <div className="empty">No network deltas recorded yet.</div>}</div></article>
        <article className="panel"><div className="panel-title"><h2>EXTRACTED NETWORK RECORDS</h2><b>{networkRows.length}</b></div><div className="network-export"><button className="secondary" onClick={() => exportNetwork('json')}>EXPORT JSON</button><button className="secondary" onClick={() => exportNetwork('csv')}>EXPORT CSV</button><button className="danger" onClick={() => void run(() => window.xls.clearRelationships(networkProfile || undefined), 'Network records cleared.')}>CLEAR FILTERED SOURCE NETWORK</button></div><div className="network-list">{networkRows.map((r) => <article key={r.id} className="network-row"><button className="network-avatar" onClick={() => void run(() => window.xls.openRelationshipProfile(r.id), 'Profile opened.')}><IdentityAvatar username={r.username} preferredUrl={r.avatar} size="md" /></button><button className="network-name" onClick={() => void run(() => window.xls.openRelationshipProfile(r.id), 'Profile opened.')}><strong>{r.displayName}</strong><span>@{r.username}</span><small>{r.bio}</small></button><span className={`relationship-tag ${r.relationship}`}>{r.relationship.toUpperCase()}</span><span className="observed">first {formatDate(r.firstObservedAt)}<br />last {formatDate(r.lastObservedAt)}</span><button className="secondary" onClick={() => void run(() => window.xls.openRelationshipProfile(r.id), 'Profile opened.')}>OPEN PROFILE</button></article>)}{!networkRows.length && <div className="empty">No network records match.</div>}</div></article>
      </section>}

      {tab === 'entities' && <section className="single-page"><div className="panel toolbar"><label>TYPE<select value={entityType} onChange={(e) => setEntityType(e.target.value)}><option value="all">ALL TYPES</option>{entityTypes.map((t) => <option key={t} value={t}>{t.toUpperCase()}</option>)}</select></label><label>SEARCH<input value={entityQuery} onChange={(e) => setEntityQuery(e.target.value)} placeholder="entity, domain, username, source" /></label><span>{entities.length} entities</span></div><div className="entity-grid">{entities.map((e) => <article className="entity-card" key={e.id}><div className="entity-heading">{e.type === 'mention' && <IdentityAvatar username={e.normalizedValue} preferredUrl={avatarFor(e.normalizedValue)} size="sm" />}<div><span className="entity-type">{e.type}</span><strong>{e.value}</strong></div></div><b>{e.count} FINDINGS</b><div className="entity-sources">{e.sourceUsernames.length ? e.sourceUsernames.map((u) => <span key={u}><IdentityAvatar username={u} preferredUrl={avatarFor(u)} size="xs" />@{u}</span>) : <small>sources: —</small>}</div><small>first {formatDate(e.firstObservedAt)} · last {formatDate(e.lastObservedAt)}</small>{e.type === 'mention' && <button onClick={() => openIdentity(e.normalizedValue)}>OPEN X PROFILE</button>}</article>)}{!entities.length && <div className="empty-large">No extracted entities match.</div>}</div></section>}

      {tab === 'changes' && <section className="single-page"><div className="two-col"><article className="panel"><div className="panel-title"><h2>HISTORICAL CHANGE EVENTS</h2><b>{recentChanges.length}</b></div><div className="event-list">{recentChanges.map((e) => <div className="event" key={e.id}><time>{formatDate(e.observedAt)}</time><strong>{e.type.replaceAll('_', ' ').toUpperCase()}</strong><span>{e.summary}</span>{e.sourceUsername && <small className="inline-identity"><IdentityAvatar username={e.sourceUsername} preferredUrl={avatarFor(e.sourceUsername)} size="xs" />@{e.sourceUsername}</small>}</div>)}{!recentChanges.length && <div className="empty">No profile/post changes recorded yet.</div>}</div></article><article className="panel"><div className="panel-title"><h2>COLLECTION RUN LOG</h2><b>{recentRuns.length}</b></div><div className="run-log">{recentRuns.map((r) => <div key={r.id} className={`run-row ${r.status}`}><div><strong className="inline-identity"><IdentityAvatar username={r.username} preferredUrl={avatarFor(r.username)} size="xs" />@{r.username} · {r.operation.toUpperCase()}</strong><span>{formatDate(r.startedAt)}</span></div><span>{r.observed} observed</span><span>{r.added} new</span><span>{r.duplicates} duplicate</span><span>{r.passesCompleted}/{r.requestedPasses || '—'} passes</span><b>{r.error ? 'ERROR' : r.stopReason || 'COMPLETE'}</b></div>)}{!recentRuns.length && <div className="empty">No collection runs logged.</div>}</div></article></div></section>}

      {tab === 'search' && <section className="single-page search-page"><div className="panel search-controls"><label>SEARCH LOCAL ARCHIVE<input value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="keyword, phrase, username, or analyst note" /></label><label>SOURCE<select value={searchProfile} onChange={(e) => setSearchProfile(e.target.value)}><option value="all">ALL SOURCES</option>{state.profiles.map((p) => <option key={p.id} value={p.id}>@{p.username}</option>)}</select></label><label>TYPE<select value={searchKind} onChange={(e) => setSearchKind(e.target.value as 'all' | PostKind)}><option value="all">ALL TYPES</option>{(Object.keys(kindLabels) as PostKind[]).map((k) => <option key={k} value={k}>{kindLabels[k]}</option>)}</select></label><label className="check preset-only"><input type="checkbox" checked={presetMatchesOnly} onChange={(e) => setPresetMatchesOnly(e.target.checked)} />PRESET MATCHES ONLY</label><strong>{searchResults.length} RESULTS</strong></div><div className="search-preset-layout"><form className="panel preset-form" onSubmit={(e) => { e.preventDefault(); const keywords = presetKeywords.split(/[,\n]/).map((x) => x.trim()).filter(Boolean); void run(async () => { await window.xls.savePreset({ id: editingPresetId || undefined, name: presetName, keywords, mode: presetMode, caseSensitive: presetCase, profileIds: presetProfiles, enabled: true }); clearPresetEditor(); }, editingPresetId ? 'Preset updated.' : 'Preset saved.'); }}><div className="panel-title"><h2>{editingPresetId ? 'EDIT HIGHLIGHT PRESET' : 'NEW HIGHLIGHT PRESET'}</h2><b>{state.presets.length} SAVED</b></div><label>PRESET NAME<input value={presetName} onChange={(e) => setPresetName(e.target.value)} placeholder="Ransomware terms / News alerts / Safeguarding" /></label><label>KEYWORDS / PHRASES<textarea value={presetKeywords} onChange={(e) => setPresetKeywords(e.target.value)} placeholder="one phrase per line or comma separated" /></label><div className="inline"><label>MODE<select value={presetMode} onChange={(e) => setPresetMode(e.target.value as 'any' | 'all')}><option value="any">MATCH ANY</option><option value="all">MATCH ALL</option></select></label><label className="check"><input type="checkbox" checked={presetCase} onChange={(e) => setPresetCase(e.target.checked)} />CASE SENSITIVE</label></div><div className="preset-profile-grid">{state.profiles.map((p) => <label className="check profile-check" key={p.id}><input type="checkbox" checked={presetProfiles.includes(p.id)} onChange={(e) => setPresetProfiles(e.target.checked ? [...presetProfiles, p.id] : presetProfiles.filter((id) => id !== p.id))} /><IdentityAvatar username={p.username} preferredUrl={p.avatar || avatarFor(p.username)} size="xs" />@{p.username}</label>)}</div><div className="card-actions"><button>{editingPresetId ? 'SAVE CHANGES' : 'ADD PRESET'}</button>{editingPresetId && <button type="button" className="secondary" onClick={clearPresetEditor}>CANCEL</button>}</div></form><div className="preset-list compact-presets">{state.presets.map((p) => <article className="panel preset-card" key={p.id}><div className="panel-title"><h2>{p.name}</h2><b>{p.mode.toUpperCase()}</b></div><p>{p.keywords.join(' · ')}</p><small>{p.profileIds.length ? `${p.profileIds.length} selected sources` : 'All campaign sources'} · {p.caseSensitive ? 'case sensitive' : 'case insensitive'}</small><div className="card-actions"><button className="secondary" onClick={() => editPreset(p)}>EDIT</button><button onClick={() => void run(() => window.xls.runPreset(p.id), `Preset ${p.name} evaluated.`)}>RUN</button><button className="danger" onClick={() => void run(() => window.xls.removePreset(p.id), 'Preset deleted.')}>DELETE</button></div></article>)}{!state.presets.length && <div className="empty">No highlight presets yet.</div>}</div></div><div className="post-list search-results">{searchResults.map((post) => renderPost(post, true))}{!searchResults.length && <div className="empty-large">No records match these search filters.</div>}</div></section>}

      {tab === 'notes' && <section className="single-page"><div className="panel toolbar"><label>SOURCE<select value={noteProfile} onChange={(e) => setNoteProfile(e.target.value)}><option value="all">ALL SOURCES</option>{state.profiles.map((p) => <option key={p.id} value={p.id}>@{p.username}</option>)}</select></label><label>SEARCH NOTES<input value={noteQuery} onChange={(e) => setNoteQuery(e.target.value)} /></label><span>{notedPosts.length} noted findings</span></div><div className="post-list">{notedPosts.map((post) => renderPost(post))}{!notedPosts.length && <div className="empty-large">No investigative notes match.</div>}</div></section>}

      {tab === 'exports' && <section className="single-page"><div className="panel export-panel"><h2>CAMPAIGN-SCOPED EVIDENCE EXPORT</h2><p>Exports include provenance fields, analyst notes, record-level evidence hashes, and a SHA-256 checksum sidecar for the exported file.</p><div className="export-filters"><label>SOURCE<select value={exportFilters.profileId || ''} onChange={(e) => setExportFilters({ ...exportFilters, profileId: e.target.value || undefined })}><option value="">ALL SOURCES</option>{state.profiles.map((p) => <option key={p.id} value={p.id}>@{p.username}</option>)}</select></label><label>TYPE<select value={exportFilters.kind || 'all'} onChange={(e) => setExportFilters({ ...exportFilters, kind: e.target.value as 'all' | PostKind })}><option value="all">ALL TYPES</option>{(Object.keys(kindLabels) as PostKind[]).map((k) => <option value={k} key={k}>{kindLabels[k]}</option>)}</select></label><label>QUERY<input value={exportFilters.query || ''} onChange={(e) => setExportFilters({ ...exportFilters, query: e.target.value || undefined })} /></label></div><div className="export-actions"><button onClick={() => exportData('json')}>EXPORT JSON + HASH</button><button onClick={() => exportData('pdf')}>EXPORT PDF + HASH</button></div></div></section>}

      {tab === 'cases' && <section className="single-page"><div className="panel campaign-head"><div><h2>CAMPAIGN WORKSPACES</h2><p>Each campaign keeps its own sources, collected findings, follower network, presets, analyst notes, archive settings, and purpose.</p></div><button onClick={startNewCampaign}>+ NEW CAMPAIGN</button></div><div className="case-grid">{state.cases.map((c) => <article className={`case-card ${c.id === state.activeCaseId ? 'active' : ''}`} key={c.id}><div><strong>{c.name}</strong><span>{c.id === state.activeCaseId ? 'ACTIVE CAMPAIGN' : 'INACTIVE'}</span></div><h4>{c.purpose || 'No purpose defined'}</h4><p>{c.description || 'No additional description.'}</p><small>Created {formatDate(c.createdAt)}</small><div className="card-actions"><button disabled={c.id === state.activeCaseId || progress.running} onClick={() => void run(() => window.xls.switchCampaign(c.id), `Switched to ${c.name}.`)}>ACTIVATE</button><button className="secondary" onClick={() => editCampaign(c)}>EDIT</button><button className="secondary" onClick={() => void run(() => window.xls.duplicateCampaign(c.id), `Duplicated ${c.name} setup.`)}>DUPLICATE SETUP</button><button className="danger" disabled={state.cases.length <= 1} onClick={() => deleteCampaign(c)}>DELETE</button></div></article>)}</div></section>}

      {tab === 'system' && <section className="system-grid"><div className="panel"><h2>X SESSION</h2><div className={`connection-banner ${sessionConnected ? 'connected' : ''}`}>{sessionConnected ? 'CONNECTED' : 'NOT CONNECTED'}</div><p>Dedicated authenticated Chromium partition. The collector stops on verification or temporary-limit screens rather than attempting to bypass them.</p><div className="card-actions"><button onClick={() => void run(window.xls.connectX, 'X login window opened.')}>CONNECT / REOPEN X</button><button className="danger" onClick={() => void run(window.xls.clearSession, 'X session cleared.')}>CLEAR SESSION</button></div></div>
        <form className="panel settings-form" onSubmit={(e) => { e.preventDefault(); void run(() => window.xls.saveSettings(settingsDraft), 'Settings saved.'); }}><h2>COLLECTION SETTINGS</h2><label className="check"><input type="checkbox" checked={settingsDraft.autoSweep} onChange={(e) => setSettingsDraft({ ...settingsDraft, autoSweep: e.target.checked })} />AUTOMATIC SWEEPS</label><div className="settings-divider">RECORD TYPES</div><label className="check"><input type="checkbox" checked={settingsDraft.collectReplies} onChange={(e) => setSettingsDraft({ ...settingsDraft, collectReplies: e.target.checked })} />COLLECT SOURCE REPLIES</label><label className="check"><input type="checkbox" checked={settingsDraft.collectReposts} onChange={(e) => setSettingsDraft({ ...settingsDraft, collectReposts: e.target.checked })} />COLLECT REPOSTS</label><label className="check"><input type="checkbox" checked={settingsDraft.collectComments} onChange={(e) => setSettingsDraft({ ...settingsDraft, collectComments: e.target.checked })} />COLLECT THIRD-PARTY COMMENTS</label><label className="check"><input type="checkbox" checked={settingsDraft.collectImages} onChange={(e) => setSettingsDraft({ ...settingsDraft, collectImages: e.target.checked })} />RETRIEVE + ARCHIVE IMAGES</label><label>COMMENT THREADS PER SOURCE<input type="number" min="1" max="20" value={settingsDraft.commentThreadsPerSweep} onChange={(e) => setSettingsDraft({ ...settingsDraft, commentThreadsPerSweep: Number(e.target.value) })} /></label><label>COMMENT SCROLL PASSES<input type="number" min="1" max="12" value={settingsDraft.commentScrollPasses} onChange={(e) => setSettingsDraft({ ...settingsDraft, commentScrollPasses: Number(e.target.value) })} /></label>
        <div className="settings-divider">TIMING + COLLECTION HEALTH</div><label>SWEEP INTERVAL MINUTES<input type="number" min="5" max="1440" value={settingsDraft.intervalMinutes} onChange={(e) => setSettingsDraft({ ...settingsDraft, intervalMinutes: Number(e.target.value) })} /></label><label>PROFILE SCROLL PASSES<input type="number" min="1" max="20" value={settingsDraft.scrollPasses} onChange={(e) => setSettingsDraft({ ...settingsDraft, scrollPasses: Number(e.target.value) })} /></label><label>FOLLOWER/FOLLOWING BASE PASSES<input type="number" min="1" max="60" value={settingsDraft.relationshipScrollPasses} onChange={(e) => setSettingsDraft({ ...settingsDraft, relationshipScrollPasses: Number(e.target.value) })} /></label><label>NETWORK STAGNATION LIMIT<input type="number" min="4" max="20" value={settingsDraft.networkStagnationLimit} onChange={(e) => setSettingsDraft({ ...settingsDraft, networkStagnationLimit: Number(e.target.value) })} /></label><label>NETWORK SNAPSHOTS RETAINED<input type="number" min="5" max="100" value={settingsDraft.networkSnapshotLimit} onChange={(e) => setSettingsDraft({ ...settingsDraft, networkSnapshotLimit: Number(e.target.value) })} /></label><label>DELAY PER PASS MS<input type="number" min="500" max="5000" step="100" value={settingsDraft.scrollDelayMs} onChange={(e) => setSettingsDraft({ ...settingsDraft, scrollDelayMs: Number(e.target.value) })} /></label><label>LOCAL POST RETENTION LIMIT<input type="number" min="1000" max="250000" step="1000" value={settingsDraft.retentionLimit} onChange={(e) => setSettingsDraft({ ...settingsDraft, retentionLimit: Number(e.target.value) })} /></label>
        <div className="settings-divider">INCREMENTAL ARCHIVE</div><label className="check"><input type="checkbox" checked={settingsDraft.archiveEnabled} onChange={(e) => setSettingsDraft({ ...settingsDraft, archiveEnabled: e.target.checked })} />ENABLE ARCHIVE CYCLES</label><label>ARCHIVE INTERVAL MINUTES<input type="number" min="30" max="10080" step="30" value={settingsDraft.archiveIntervalMinutes} onChange={(e) => setSettingsDraft({ ...settingsDraft, archiveIntervalMinutes: Number(e.target.value) })} /></label><label>POST DEPTH ADDED / CYCLE<input type="number" min="1" max="20" value={settingsDraft.archivePostStep} onChange={(e) => setSettingsDraft({ ...settingsDraft, archivePostStep: Number(e.target.value) })} /></label><label>MAX POST DEPTH<input type="number" min="5" max="120" value={settingsDraft.archivePostMaxPasses} onChange={(e) => setSettingsDraft({ ...settingsDraft, archivePostMaxPasses: Number(e.target.value) })} /></label><label className="check"><input type="checkbox" checked={settingsDraft.archiveFollowers} onChange={(e) => setSettingsDraft({ ...settingsDraft, archiveFollowers: e.target.checked })} />ARCHIVE FOLLOWERS</label><label className="check"><input type="checkbox" checked={settingsDraft.archiveFollowing} onChange={(e) => setSettingsDraft({ ...settingsDraft, archiveFollowing: e.target.checked })} />ARCHIVE FOLLOWING</label><label>NETWORK DEPTH ADDED / CYCLE<input type="number" min="1" max="40" value={settingsDraft.archiveRelationshipStep} onChange={(e) => setSettingsDraft({ ...settingsDraft, archiveRelationshipStep: Number(e.target.value) })} /></label><label>MAX NETWORK DEPTH<input type="number" min="8" max="240" value={settingsDraft.archiveRelationshipMaxPasses} onChange={(e) => setSettingsDraft({ ...settingsDraft, archiveRelationshipMaxPasses: Number(e.target.value) })} /></label><button>SAVE SETTINGS</button></form>
        <div className="panel archive-panel"><div className="panel-title"><h2>INCREMENTAL ARCHIVE STATUS</h2><b>{state.settings.archiveEnabled ? 'ENABLED' : 'DISABLED'}</b></div><p>The follower/following collector now keeps a page-side MutationObserver accumulator so virtualized X user cells remain in the current scan even after they scroll out of the DOM. Archive depth continues increasing across cycles, while collection runs report whether progress is new, duplicate-heavy, or plateaued.</p><div className="archive-summary"><article className="stat"><span>ARCHIVE CYCLES</span><strong>{state.archive?.cyclesCompleted || 0}</strong><small>{formatDate(state.archive?.lastCycleAt)}</small></article><article className="stat"><span>OPERATIONS</span><strong>{archiveOperationCount}</strong><small>current campaign rotation</small></article><article className="stat"><span>OLDEST LOCAL POST</span><strong className="date-stat">{formatDate(oldestArchivedPost)}</strong></article></div><div className="archive-actions"><button disabled={progress.running || !state.profiles.length} onClick={runArchiveStep}>RUN ONE ARCHIVE STEP</button><button className="danger" onClick={() => void run(window.xls.resetArchiveProgress, 'Archive depth counters reset for active campaign.')}>RESET CAMPAIGN DEPTH COUNTERS</button></div><div className="archive-profile-list">{archiveRows.map(({ profile, progress: r }) => <article key={profile.id}><div><strong className="inline-identity"><IdentityAvatar username={profile.username} preferredUrl={profile.avatar || avatarFor(profile.username)} size="xs" />@{profile.username}</strong><span>oldest {formatDate(r?.oldestPostAt)}</span></div><div className="archive-depths"><span>POSTS {r?.postPasses || settingsDraft.scrollPasses}</span><span>FOLLOWERS {r?.followerPasses || settingsDraft.relationshipScrollPasses}</span><span>FOLLOWING {r?.followingPasses || settingsDraft.relationshipScrollPasses}</span></div></article>)}</div></div>
        <div className="panel"><h2>LOCAL CAMPAIGN DATA</h2><p>Clearing data affects only the active campaign. X login/session storage is shared by the application.</p><div className="card-actions"><button className="secondary" onClick={() => void run(window.xls.loadDemo, 'Demo records loaded into active campaign.')}>LOAD DEMO DATA</button><button className="danger" onClick={() => void run(window.xls.clearCollectedData, 'Active campaign feed data cleared.')}>CLEAR CAMPAIGN FEED DATA</button><button className="danger" onClick={() => void run(() => window.xls.clearRelationships(), 'Active campaign network data cleared.')}>CLEAR CAMPAIGN NETWORK DATA</button></div></div>
      </section>}
    </main>
    {campaignEditorOpen && <div className="modal-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) setCampaignEditorOpen(false); }}><div className="modal-card"><div className="panel-title"><h2>{campaignEditorId ? 'EDIT CAMPAIGN' : 'CREATE CAMPAIGN'}</h2><button className="secondary" onClick={() => setCampaignEditorOpen(false)}>CLOSE</button></div><label>CAMPAIGN NAME<input autoFocus value={caseName} onChange={(e) => setCaseName(e.target.value)} placeholder="Threat Intelligence / News Monitoring / Child Protection" /></label><label>PURPOSE<input value={casePurpose} onChange={(e) => setCasePurpose(e.target.value)} placeholder="User-defined purpose for this workspace" /></label><label>DESCRIPTION / NOTES<textarea value={caseDescription} onChange={(e) => setCaseDescription(e.target.value)} placeholder="Optional scope, client, collection goals, handling notes…" /></label><div className="card-actions"><button disabled={!caseName.trim()} onClick={saveCampaign}>{campaignEditorId ? 'SAVE CAMPAIGN' : 'CREATE + ACTIVATE'}</button><button className="secondary" onClick={() => setCampaignEditorOpen(false)}>CANCEL</button></div></div></div>}
  </div>;
}


